{
  "API_calls": [],
  "collected_information": {
    "Makefile_init_target": {
      "tools_required": ["uv", "npm"],
      "commands": [
        "uv sync --frozen --extra \"postgresql\" $(EXTRA_ARGS)",
        "make install_frontend (delegated to Makefile.frontend)",
        "uvx pre-commit install"
      ]
    },
    "Makefile_frontend": {
      "frontend_directory": "src/frontend",
      "commands": {
        "install_frontend": "cd src/frontend && npm install",
        "install_frontendci": "cd src/frontend && npm ci",
        "install_frontendc": "clean node_modules and package-lock.json then npm install",
        "build_frontend": "cd src/frontend && CI='' npm run build",
        "dev_server": "cd src/frontend && npm start with FRONTEND_START_FLAGS",
        "format_code": "cd src/frontend && npm run format",
        "testing": [
          "cd src/frontend && npm test",
          "npx jest with options",
          "cd src/frontend && npx playwright test --project=chromium"
        ]
      }
    },
    "README_md": {
      "python_version": "3.10 to 3.13",
      "installation": "uv pip install langflow -U",
      "run": "uv run langflow run",
      "notes": "No explicit test commands in README.md"
    },
    ".github/workflows/python_test.yml": {
      "python_versions": ["3.10", "3.11", "3.12", "3.13"],
      "node_version": "21",
      "tools": ["uv", "poetry v1.8.2"],
      "env_vars_required": ["OPENAI_API_KEY", "ANTHROPIC_API_KEY", "CODECOV_TOKEN (optional)"],
      "test_commands": {
        "unit_tests": "make unit_tests args=\"-x -vv --splits 5 --group <group_number> --reruns 5 --cov --cov-config=src/backend/.coveragerc --cov-report=xml --cov-report=html\"",
        "integration_tests": "make integration_tests_no_api_keys with env vars PYLEAK_LOG_LEVEL=debug, DO_NOT_TRACK=true",
        "lfx_tests": "make lfx_tests with DO_NOT_TRACK=true",
        "cli_tests": "build wheel, run python -m langflow run --host localhost --port 7860 --backend-only"
      },
      "coverage": "xml and html reports generated"
    },
    ".github/workflows/jest_test.yml": {
      "node_version": "21",
      "cache": "caches npm deps from src/frontend/package-lock.json",
      "frontend_test_command": "make test_frontend_ci",
      "coverage_reports": {
        "coverage_dir": "src/frontend/coverage/",
        "test_results_dir": "src/frontend/test-results/"
      },
      "publish": "Optional Codecov upload"
    },
    "scripts/ci": "No test scripts found, only update/version management scripts"
  },
  "terminate": true
}
